async function loadItems(append=false){const version=++state.listVersion;state.listController?.abort();const controller=new AbortController();state.listController=controller;const params=new URLSearchParams({limit:"50",sort:state.sort});if(state.page==="papers")params.set("kind","paper");if(state.query)params.set("q",state.query);if(state.tag)params.set("tag",state.tag);if(state.untagged)params.set("untagged","1");if(state.status)params.set("status",state.status);if(append&&state.cursor)params.set("cursor",state.cursor);try{const data=await api("/api/items?"+params,{signal:controller.signal});if(version!==state.listVersion)return false;state.items=append?state.items.concat(data.items):data.items;state.total=data.total;state.cursor=data.next_cursor;if(!append)state.selectedIds.clear();return true;}catch(error){if(error.name==="AbortError")return false;throw error;}finally{if(state.listController===controller)state.listController=null;}}
function relative(value){if(!value)return "刚刚";const age=Date.now()-new Date(value);if(age<60000)return "刚刚";if(age<3600000)return Math.floor(age/60000)+" 分钟前";if(age<86400000)return Math.floor(age/3600000)+" 小时前";if(age<604800000)return Math.floor(age/86400000)+" 天前";return new Date(value).toLocaleDateString("zh-CN",{month:"short",day:"numeric"});}
