  root.dataset.mode=state.mode;state.toolbar?.hideTooltip?.();
  const title=$("#edit-title"),toggle=$("#outline-toggle"),modes=root.querySelector('.view-modes'),subline=root.querySelector('.document-subline');
  const active=document.activeElement,range=active===title?[title.selectionStart,title.selectionEnd]:null;
