  const actions=root.querySelector('.document-actions'),focusLeft=root.querySelector('.focus-left-controls'),focusViewControls=root.querySelector('.focus-view-controls'),focusToolsButton=$("#focus-tools-toggle"),focusButton=$("#focus-mode"),inspector=$("#inspector-toggle");
