async function loadLinkCandidates(query){const version=++linkVersion;try{const data=await api("/api/item-candidates?limit=50&exclude_id="+(state.current?.id||0)+"&q="+encodeURIComponent(query));if(version!==linkVersion)return;$("#link-results").innerHTML=data.items.length?data.items.map(item=>'<button class="picker-row" data-link-id="'+item.id+'">'+icon(documentIcon(item.kind))+'<span><strong>'+esc(item.title)+'</strong><small>'+esc(kindNames[item.kind])+'</small></span><span>↗</span></button>').join(""):'<p class="empty-hint">没有可关联的文档。请修改关键词，或先创建另一份文档。</p>';$("#link-results").querySelectorAll("[data-link-id]").forEach(button=>button.onclick=()=>{const item=data.items.find(x=>x.id===Number(button.dataset.linkId));state.editor.insertReference(item);if(!state.pendingLinks.includes(item.id))state.pendingLinks.push(item.id);writeDraft();$("#link-dialog").close();toast("已插入文档链接，保存时更新关联");});}catch(error){$("#link-results").textContent=error.message;}}
