async function renderRelations(query=""){
  const root=$("#page-content");root.innerHTML='<div class="standalone-page relations-page"><div class="standalone-heading"><div><h1>文档关系</h1><p>从列表选择文档，查看其上级、下级和关联文档。</p></div></div><div class="relation-workspace"><aside class="relation-picker"><div class="list-search">'+icon("search")+'<input id="relation-search" type="search" placeholder="搜索文档标题…" aria-label="搜索关系文档"></div><div id="relation-documents"></div></aside><section id="relation-map" class="relation-map"></section></div></div>';
  $("#relation-search").value=query;$("#relation-search").oninput=event=>{clearTimeout(state.relationTimer);const q=event.target.value;state.relationTimer=setTimeout(()=>{state.relationTimer=0;loadRelationGraph(q);},180);};await loadRelationGraph(query);
}
async function loadRelationGraph(query=""){
  const version=++state.relationVersion;state.relationController?.abort();const controller=new AbortController();state.relationController=controller;
  try{const data=await api("/api/graph?limit=200"+(query?"&q="+encodeURIComponent(query):""),{signal:controller.signal});if(version!==state.relationVersion||state.page!=="relations")return;state.relationData=data;if(!data.nodes.some(n=>n.id===state.relationFocus))state.relationFocus=data.nodes[0]?.id||null;$("#relation-documents").innerHTML=data.nodes.length?data.nodes.map(node=>'<button class="relation-picker-row" data-focus-id="'+node.id+'">'+icon(documentIcon(node.kind))+'<span>'+esc(node.title)+'</span></button>').join(""):'<p class="empty-hint">还没有匹配的文档。</p>';$("#relation-documents").querySelectorAll("button").forEach(button=>button.onclick=()=>{state.relationFocus=Number(button.dataset.focusId);drawRelationMap();});drawRelationMap();}catch(error){if(error.name!=="AbortError"&&version===state.relationVersion&&state.page==="relations")toast(error.message,true);}finally{if(state.relationController===controller)state.relationController=null;}}
function drawRelationMap(){
  const root=$("#relation-map"),data=state.relationData;if(!root||!data)return;const current=data.nodes.find(n=>n.id===state.relationFocus);
  $("#relation-documents").querySelectorAll("[data-focus-id]").forEach(button=>button.classList.toggle("is-active",Number(button.dataset.focusId)===current?.id));
  if(!current){root.innerHTML='<div class="relation-empty">'+icon("relations")+'<h2>暂无文档关系</h2><p>在文档编辑器中点击“链接文档”，或在“文档信息”中设置“上级文档”。</p></div>';return;}
  const parents=[],children=[],related=[];for(const edge of data.edges){const source=edge.source_id,target=edge.target_id;if(source!==current.id&&target!==current.id)continue;const other=data.nodes.find(n=>n.id===(source===current.id?target:source));if(!other)continue;if(edge.kind==="hierarchy"){if(target===current.id)parents.push(other);else children.push(other);}else related.push(other);}
  const cards=(nodes,type)=>nodes.length?nodes.map(n=>'<button class="map-node" data-map-focus="'+n.id+'"><small>'+esc(type)+'</small><strong>'+esc(n.title)+'</strong><span>'+esc(kindNames[n.kind])+'</span></button>').join(""):'<div class="map-placeholder">'+(type==="上级文档"?"还没有上级文档":"还没有下级文档")+'</div>';
  root.innerHTML='<div class="map-caption"><span>当前文档及相邻关系</span><span>'+((data.truncated?"仅显示前 "+data.nodes.length+" 份文档 · ":""))+(parents.length+children.length+related.length)+' 条连接</span></div><div class="map-hierarchy"><div class="map-column">'+cards(parents,"上级文档")+'</div><span class="map-connector" aria-hidden="true">—</span><button id="map-current" class="map-node map-current"><small>'+esc(kindNames[current.kind])+'</small><strong>'+esc(current.title)+'</strong><span>打开文档 '+icon("arrow")+'</span></button><span class="map-connector" aria-hidden="true">—</span><div class="map-column">'+cards(children,"下级文档")+'</div></div><div class="map-related"><div class="section-label">关联文档</div><div class="map-related-grid">'+(related.length?related.map(n=>'<button class="map-related-card" data-map-focus="'+n.id+'">'+icon(documentIcon(n.kind))+'<span>'+esc(n.title)+'</span><span>↗</span></button>').join(""):'<p class="quiet">打开文档后点击“链接文档”添加关联。</p>')+'</div></div>';
  $("#map-current").onclick=()=>openDocument(current.id);root.querySelectorAll("[data-map-focus]").forEach(button=>button.onclick=()=>{state.relationFocus=Number(button.dataset.mapFocus);drawRelationMap();});
}
async function renderTrash(itemOffset=0,fileOffset=0){const data=await api("/api/trash?item_offset="+itemOffset+"&file_offset="+fileOffset);$("#page-content").innerHTML='<div class="standalone-page"><div class="standalone-heading"><div><h1>回收站</h1><p>误删的文档和附件可以在这里恢复。</p></div></div><div class="trash-grid">'+[["items","文档",data.items],["files","附件",data.files]].map(([type,label,rows])=>'<section class="plain-card"><div class="section-label">'+label+' · '+data.totals[type]+'</div>'+(rows.length?rows.map(item=>'<div class="trash-row"><div><strong>'+esc(item.title||item.name)+'</strong><small>'+esc(relative(item.deleted_at))+'</small></div><button class="button secondary small" data-trash-restore="'+type+':'+item.id+'">恢复</button><button class="quiet-button danger" data-trash-purge="'+type+':'+item.id+'">永久删除</button></div>').join(""):'<p class="empty-hint">这里是空的。</p>')+(data.next_offsets[type]!=null?'<button class="quiet-button" data-trash-more="'+type+'">加载更多</button>':"")+'</section>').join("")+'</div></div>';
  $$("[data-trash-restore]").forEach(button=>button.onclick=async()=>{const [type,id]=button.dataset.trashRestore.split(":");try{await post("/api/trash/"+type+"/"+id+"/restore",{});await renderTrash(itemOffset,fileOffset);refreshSidebar();toast("已恢复");}catch(error){toast(error.message,true);}});$$("[data-trash-purge]").forEach(button=>button.onclick=async()=>{if(!window.confirm("永久删除后无法恢复，确定继续吗？"))return;const [type,id]=button.dataset.trashPurge.split(":");try{await api("/api/trash/"+type+"/"+id,{method:"DELETE"});await renderTrash(itemOffset,fileOffset);toast("已永久删除");}catch(error){toast(error.message,true);}});$$("[data-trash-more]").forEach(button=>button.onclick=()=>renderTrash(button.dataset.trashMore==="items"?data.next_offsets.items:itemOffset,button.dataset.trashMore==="files"?data.next_offsets.files:fileOffset));
}
async function renderFiles(){const data=await api("/api/files?limit=200");$("#page-content").innerHTML='<div class="standalone-page"><div class="standalone-heading"><div><h1>附件管理</h1><p>图片、PDF 和其他附件。'+data.total+' 个文件 · '+formatBytes(data.total_bytes)+'</p></div></div><section class="plain-card file-manager">'+(data.files.length?data.files.map(file=>'<div class="managed-file"><a href="/files/'+file.id+'" target="_blank" rel="noopener">'+icon(file.content_type==="application/pdf"?"book":"document")+'<span><strong>'+esc(file.name)+'</strong><small>'+formatBytes(file.size)+(file.item_title?" · "+esc(file.item_title):" · 未关联文档")+'</small></span></a><button class="quiet-button" data-file-preview="'+file.id+'">打开</button><button class="quiet-button danger" data-file-trash="'+file.id+'">移入回收站</button></div>').join(""):'<p class="empty-hint">在文档中粘贴图片或上传 PDF，附件就会出现在这里。</p>')+'</section></div>';$$("[data-file-preview]").forEach(button=>button.onclick=()=>window.open("/files/"+button.dataset.filePreview+"?inline=1","_blank","noopener"));$$("[data-file-trash]").forEach(button=>button.onclick=async()=>{if(!window.confirm("将这个附件移入回收站？正文中的引用将暂时无法预览。"))return;try{await api("/api/files/"+button.dataset.fileTrash,{method:"DELETE"});await renderFiles();}catch(error){toast(error.message,true);}});}
function highlightSearchText(value,query){const raw=String(value??""),terms=[...new Set(String(query||"").trim().split(/\s+/).filter(Boolean))].sort((a,b)=>b.length-a.length).map(term=>term.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"));if(!terms.length)return esc(raw);const matcher=new RegExp(terms.join("|"),"giu");let match,last=0,html="";while((match=matcher.exec(raw))){html+=esc(raw.slice(last,match.index))+'<mark class="search-hit">'+esc(match[0])+'</mark>';last=matcher.lastIndex;if(!match[0])matcher.lastIndex++;}return html+esc(raw.slice(last));}
let searchTimer,searchVersion=0;$("#global-search").oninput=event=>{clearTimeout(searchTimer);const query=event.target.value;searchTimer=setTimeout(()=>searchGlobal(query),160);};
async function searchGlobal(query){const version=++searchVersion,root=$("#search-results");state.searchController?.abort();if(!query.trim()){root.innerHTML='<p class="empty-hint">输入关键词开始搜索。</p>';return;}state.searchController=new AbortController();try{const data=await api("/api/search?limit=50&q="+encodeURIComponent(query),{signal:state.searchController.signal});if(version!==searchVersion)return;root.innerHTML=data.items.length||data.files.length?data.items.map(item=>'<button class="search-result" data-search-id="'+item.id+'">'+icon(documentIcon(item.kind))+'<span><strong>'+highlightSearchText(item.title,query)+'</strong><p>'+highlightSearchText(item.snippet||item.summary||"",query)+'</p><small>'+esc(kindNames[item.kind])+" · "+relative(item.updated_at)+'</small></span></button>').join("")+data.files.map(file=>'<a class="search-result" href="/files/'+file.id+'" target="_blank" rel="noopener">'+icon("document")+'<span><strong>'+highlightSearchText(file.name,query)+'</strong><small>附件 · '+formatBytes(file.size)+'</small></span></a>').join(""):'<p class="empty-hint">没有找到匹配的内容。</p>';root.querySelectorAll("[data-search-id]").forEach(button=>button.onclick=async()=>{if(!canLeave())return;$("#search-dialog").close();await openDocument(button.dataset.searchId,true);});}catch(error){if(error.name!=="AbortError")root.innerHTML='<p class="error">'+esc(error.message)+'</p>';}}
